from decimal import Decimal, ROUND_HALF_UP, ROUND_HALF_DOWN


def normalise(reading_m: float) -> float:
    """Round a reading to two decimals, away from zero at the midpoint."""
    d = Decimal(str(reading_m))
    if d >= 0:
        result = d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    else:
        result = d.quantize(Decimal("0.01"), rounding=ROUND_HALF_DOWN)
    return float(result)

